import {Pool,PostgresUnitOfWork} from '@storymaster/infrastructure';
import {ProposalService} from '@storymaster/application';
import type {Transaction,UnitOfWork} from '@storymaster/application';
import type {Actor} from '@storymaster/domain';
process.once('message',async(raw:unknown)=>{const input=raw as {actor:Actor;projectId:string;proposalId:string;proposalRevision:number;stateVersion:number;key:string;secret:string;phase:'before_commit'|'after_commit'},url=process.env.TEST_APP_DATABASE_URL;if(!url||!new URL(url).pathname.endsWith('_test'))throw Error('Base de crash dédiée requise.');const pool=new Pool({connectionString:url,max:1,application_name:'storymaster-lot4-process-crash'}),real=new PostgresUnitOfWork(pool),barrier=()=>new Promise<never>(()=>{}),unit:UnitOfWork={async transaction<T>(work:(tx:Transaction)=>Promise<T>){const result=await real.transaction(async tx=>{const r=await work(tx);if(input.phase==='before_commit'){process.send?.({phase:input.phase});await barrier();}return r;});process.send?.({phase:'after_commit',result});await barrier();return result;}};try{await new ProposalService(unit,input.secret).merge(input.actor,input.projectId,input.proposalId,input.proposalRevision,input.stateVersion,input.key,crypto.randomUUID());}catch(e){process.send?.({error:e instanceof Error?e.name:'Unknown'});await pool.end();process.exitCode=1;process.disconnect?.();}});
